// ─── Anti-drift marker verification ──────────────────────────────────────────
// 10 canonical markers that KRITE checks byte-for-byte
const ANTI_DRIFT_CANONICAL_MARKERS = [
  "EVIDENCE-OR-INCOMPLETE RULE",
