function verifyAntiDriftBlockPresent(blockText) {
  const missing = [];
  for (const marker of ANTI_DRIFT_CANONICAL_MARKERS) {
    if (!blockText.includes(marker)) {
      missing.push(marker);
    }
  }
  return { valid: missing.length === 0, missing };
}

// ─── System prompt for the self-test Claude call ─────────────────────────────
